package com.smartsociety.platform.config;import com.smartsociety.platform.auth.*;import com.smartsociety.platform.common.Enums.Role;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;@Configuration public class DemoDataConfig{@Bean CommandLineRunner seed(@Value("${app.seed-demo:false}")boolean enabled,UserRepository users,PasswordEncoder enc){return args->{if(!enabled||users.count()>0)return;var a=new User();a.setEmail("admin@smartsociety.local");a.setFullName("Society Admin");a.setRole(Role.ADMIN);a.setPasswordHash(enc.encode("ChangeMe123!"));users.save(a);var r=new User();r.setEmail("resident@smartsociety.local");r.setFullName("Demo Resident");r.setPasswordHash(enc.encode("ChangeMe123!"));users.save(r);};}}
